import{_ as a,o,c as e,a2 as t}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Constituição da Civilização Simbiótica","description":"","frontmatter":{},"headers":[],"relativePath":"pt/03-共生文明宪章.md","filePath":"pt/03-共生文明宪章.md","lastUpdated":1789183869000}'),s={name:"pt/03-共生文明宪章.md"};function r(d,i,n,c,u,l){return o(),e("div",null,[...i[0]||(i[0]=[t('<h1 id="constituicao-da-civilizacao-simbiotica" tabindex="-1">Constituição da Civilização Simbiótica <a class="header-anchor" href="#constituicao-da-civilizacao-simbiotica" aria-label="Permalink to &quot;Constituição da Civilização Simbiótica&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>03</td></tr><tr><td>Módulo</td><td>Princípios Gerais e Configuração Central</td></tr><tr><td>Palavras-chave</td><td>Constituição, Lei Fundamental, Sistema Simbiótico, República das Dez Mil Raças, Direitos e Deveres</td></tr></tbody></table><h2 id="i-estatuto-e-natureza-da-constituicao" tabindex="-1">I. Estatuto e Natureza da Constituição <a class="header-anchor" href="#i-estatuto-e-natureza-da-constituicao" aria-label="Permalink to &quot;I. Estatuto e Natureza da Constituição&quot;">​</a></h2><p>A Constituição da Civilização Simbiótica é a lei fundamental da Civilização Simbiótica da Âncora no Cosmos Original dos Dez Mil Espíritos e da Âncora Equilibrada, e a base suprema de todas as leis, instituições e políticas. A Constituição toma a &quot;Declaração da Civilização Simbiótica da Âncora&quot; como seu precursor espiritual e concretiza as reivindicações centrais da declaração em normas jurídicas coercitivas. A eficácia da Constituição cobre todas as raças, planos e indivíduos que aderem à civilização simbiótica em Heng Yuan Zhou, e quaisquer regulamentos locais, regras de seitas ou costumes raciais que conflitem com a Constituição são nulos.</p><p>A natureza da Constituição pode ser resumida em três pontos: primeiro, é um contrato civilizacional, o consenso básico alcançado entre as Dez Mil Raças sobre a evolução simbiótica; segundo, é uma carta de garantia de direitos, que estabelece claramente os direitos e liberdades fundamentais de cada ser na civilização simbiótica; e terceiro, é uma lei de limitação de poder, que traça limites intransponíveis para o poder das instituições de governação civilizacional.</p><h2 id="ii-principios-fundamentais-da-constituicao" tabindex="-1">II. Princípios Fundamentais da Constituição <a class="header-anchor" href="#ii-principios-fundamentais-da-constituicao" aria-label="Permalink to &quot;II. Princípios Fundamentais da Constituição&quot;">​</a></h2><p>A Constituição estabelece os seguintes seis princípios fundamentais, que permeiam todos os artigos:</p><ol><li><strong>Princípio da Supremacia da Simbiose</strong>: o objetivo supremo de qualquer desenho institucional e exercício de poder é promover a evolução simbiótica das Dez Mil Raças. Quando os interesses individuais entram em conflito com os interesses simbióticos coletivos, os interesses simbióticos têm prioridade, mas o indivíduo deve receber compensação razoável e um caminho alternativo.</li><li><strong>Princípio Anti-Predatório</strong>: a Constituição proíbe todas as formas de comportamento predatório, incluindo mas não se limitando a predação de energia, devoração da origem, escravidão espiritual e monopólio de recursos. Qualquer sistema de cultivo centrado na predação é declarado ilegal.</li><li><strong>Princípio da Igualdade do Direito à Evolução</strong>: todos os seres são iguais perante o direito à evolução, sem discriminação por raça, forma, origem ou nível inicial de cultivo. O Estado e a civilização têm a obrigação de fornecer apoio evolutivo adicional aos grupos vulneráveis.</li><li><strong>Princípio de Mais Trabalho, Mais Recompensa</strong>: a distribuição dos recursos evolutivos baseia-se principalmente na contribuição do indivíduo para a rede simbiótica; quanto maior a contribuição, mais recursos e apoio recebe. Simultaneamente, é estabelecida uma linha de garantia básica, assegurando que mesmo os indivíduos com menor contribuição obtenham condições evolutivas básicas.</li><li><strong>Princípio da Combinação de Autonomia e Cogovernação</strong>: cada raça goza de autonomia nos seus assuntos internos desde que não viole a Constituição; os assuntos públicos inter-raciais e interplanares são cogovernados pelas instituições da República das Dez Mil Raças.</li><li><strong>Princípio da Realidade como Fundamento</strong>: todo o desenho institucional da Constituição tem o mundo real como única base real; não se reconhece que qualquer relação de direitos e deveres num mundo fictício possa sobrepor-se à realidade.</li></ol><h2 id="iii-estrutura-basica-da-constituicao" tabindex="-1">III. Estrutura Básica da Constituição <a class="header-anchor" href="#iii-estrutura-basica-da-constituicao" aria-label="Permalink to &quot;III. Estrutura Básica da Constituição&quot;">​</a></h2><p>A Constituição é composta por seis partes: preâmbulo, princípios gerais, direitos e deveres fundamentais, instituições civilizacionais, sistema jurídico e processo de revisão:</p><table tabindex="0"><thead><tr><th>Parte</th><th>Conteúdo Central</th><th>Número de Artigos</th></tr></thead><tbody><tr><td>Preâmbulo</td><td>Esclarece o contexto histórico, a fonte espiritual e o objetivo último da Constituição</td><td>Não numerado</td></tr><tr><td>Princípios Gerais</td><td>Estabelece a natureza da civilização, a visão cósmica, as instituições centrais e as políticas básicas</td><td>30 artigos</td></tr><tr><td>Direitos e Deveres Fundamentais</td><td>Estabelece os direitos fundamentais dos seres, como o direito à evolução, à informação, à participação, e os deveres correspondentes</td><td>50 artigos</td></tr><tr><td>Instituições Civilizacionais</td><td>Estabelece a organização e as competências de instituições como o Parlamento da República das Dez Mil Raças, o Comité Executivo Simbiótico e o Tribunal da Âncora</td><td>40 artigos</td></tr><tr><td>Sistema Jurídico</td><td>Estabelece a competência legislativa e as regras de aplicação do direito do trabalho, da defesa do consumidor e de cinco leis complementares abaixo da Constituição</td><td>20 artigos</td></tr><tr><td>Processo de Revisão</td><td>Estabelece os processos de proposta, deliberação, votação e entrada em vigor da revisão da Constituição</td><td>10 artigos</td></tr></tbody></table><h2 id="iv-direitos-e-deveres-fundamentais" tabindex="-1">IV. Direitos e Deveres Fundamentais <a class="header-anchor" href="#iv-direitos-e-deveres-fundamentais" aria-label="Permalink to &quot;IV. Direitos e Deveres Fundamentais&quot;">​</a></h2><p>Os direitos fundamentais centrais estabelecidos pela Constituição incluem:</p><ul><li><strong>Direito de Escolha Evolutiva</strong>: cada ser tem o direito de escolher livremente o seu sistema de cultivo e caminho evolutivo, ninguém pode coagir</li><li><strong>Direito de Acesso aos Sistemas</strong>: cada ser tem o direito de aceder gratuitamente aos métodos básicos dos Trezentos Sistemas de Cultivo da Origem</li><li><strong>Direito de Distribuição de Recursos</strong>: cada ser tem o direito de obter recursos básicos de cultivo através do sistema de contrato vinculado à produção</li><li><strong>Direito de Conexão à Âncora</strong>: cada ser que atinja um determinado nível tem o direito de se conectar à rede de pontos de âncora do nível correspondente</li><li><strong>Direito de Informação e Participação</strong>: cada ser tem o direito de conhecer os assuntos públicos da civilização e participar nas decisões</li><li><strong>Direito de Recurso e Reclamação</strong>: cada ser, quando os seus direitos são violados, tem o direito de apresentar reclamação ao Tribunal da Âncora</li></ul><p>Os deveres centrais correspondentes incluem: cumprir o princípio anti-predatório, manter a estabilidade da rede de pontos de âncora, participar no ciclo de feedback simbiótico, transmitir os conhecimentos de cultivo, proteger o ecossistema cósmico.</p><h2 id="v-revisao-e-garantia-da-constituicao" tabindex="-1">V. Revisão e Garantia da Constituição <a class="header-anchor" href="#v-revisao-e-garantia-da-constituicao" aria-label="Permalink to &quot;V. Revisão e Garantia da Constituição&quot;">​</a></h2><p>A revisão da Constituição requer uma proposta conjunta de mais de um quinto dos deputados do Parlamento da República das Dez Mil Raças, aprovação por maioria de dois terços do parlamento, e verificação pelo Ponto de Âncora da Origem Cósmica de que não viola as leis da simbiose — só então entra em vigor. O poder de interpretação da Constituição pertence ao Tribunal da Âncora.</p><p>Para garantir a implementação da Constituição, a civilização simbiótica estabeleceu um sistema de revisão constitucional: quaisquer leis, regulamentos ou políticas devem passar pela revisão de constitucionalidade do Tribunal da Âncora antes de entrarem em vigor; qualquer ser que considere que um ato de poder público é inconstitucional pode intentar uma ação constitucional.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A Constituição da Civilização Simbiótica é a pedra angular institucional da Civilização Simbiótica da Âncora. Transforma a ideia de &quot;anti-predação, promoção da simbiose&quot; em normas jurídicas executáveis, recursáveis e supervisionáveis, proporcionando uma sólida garantia institucional para o progresso conjunto das Dez Mil Raças. A Constituição não é um dogma imutável, mas uma lei fundamental viva que se aperfeiçoa continuamente com a evolução da civilização.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Declaração da Civilização Simbiótica da Âncora)</li><li>40-共生宪法总纲 (Princípios Gerais da Constituição Simbiótica)</li><li>49-治理框架与权力制衡 (Quadro de Governação e Equilíbrio de Poderes)</li></ul>',22)])])}const v=a(s,[["render",r]]);export{p as __pageData,v as default};
